using System.ComponentModel.DataAnnotations;
using Maxx.Api.Autenticacao;
using Maxx.Api.LimiteDeTaxa;
using Maxx.Application.Demonstracao;
using Microsoft.AspNetCore.Http.HttpResults;

namespace Maxx.Api.Demonstracao;

// A flag da demonstração (CLAUDE.md, Segurança): desligada por padrão e ausente de todo
// appsettings versionado. Liga-se só por variável de ambiente, no compose da apresentação.
public sealed class DemoOptions
{
    public const string Section = "Demo";

    public bool Habilitada { get; set; }

    // Gravado em cada aluno de demonstração criado enquanto vale: a chave da purga.
    public string? Lote { get; set; }
}

internal static class DemonstracaoEndpoints
{
    // Devolve se as rotas devem existir. Desligada, elas nem são mapeadas: a resposta é o
    // 404 de uma rota inexistente, byte a byte. A geração do OpenAPI as mapeia mesmo assim,
    // para o cliente ter os tipos da tela do passo 5.
    public static bool AddDemonstracao(this WebApplicationBuilder builder, bool servindo, bool gerandoOpenApi)
    {
        var opcoes = builder.Configuration.GetSection(DemoOptions.Section).Get<DemoOptions>() ?? new DemoOptions();
        if (opcoes.Habilitada && servindo && string.IsNullOrWhiteSpace(opcoes.Lote))
        {
            throw new InvalidOperationException(
                $"{DemoOptions.Section}__Habilitada sem {DemoOptions.Section}__Lote: defina o lote da apresentação.");
        }

        builder.Services.AddSingleton(new ConfiguracaoDaDemonstracao(opcoes.Lote?.Trim() ?? string.Empty));
        builder.Services.AddScoped<DemonstracaoHandler>();

        return opcoes.Habilitada || gerandoOpenApi;
    }

    public static IEndpointRouteBuilder MapDemonstracaoEndpoints(this IEndpointRouteBuilder v1)
    {
        var demo = v1.MapGroup("/demo").WithTags("Demonstracao").AllowAnonymous();

        demo.MapGet("", CursosAsync).WithName("GetDemonstracao");

        demo.MapPost("/alunos", RegistrarAsync)
            .WithName("RegistrarAlunoDeDemonstracao")
            .ProducesValidationProblem()
            .ProducesProblem(StatusCodes.Status404NotFound)
            .ProducesProblem(StatusCodes.Status409Conflict)
            .ComLimiteDeTaxa(Limite.RegistroDeDemonstracaoPorIp, contexto => LimiteDeTaxaExtensions.Ip(contexto.HttpContext));

        demo.MapPost("/entrar", EntrarAsync)
            .WithName("EntrarNaDemonstracao")
            .ProducesValidationProblem()
            .ProducesProblem(StatusCodes.Status401Unauthorized);

        return v1;
    }

    // Responder já diz que a demonstração está ligada; o corpo traz os cursos da escolha.
    private static async Task<Ok<DemonstracaoResponse>> CursosAsync(
        DemonstracaoHandler handler, CancellationToken cancellationToken) =>
        TypedResults.Ok(new DemonstracaoResponse(
            [.. (await handler.CursosAsync(cancellationToken)).Select(curso => new CursoDeDemonstracao(curso.Sigla, curso.Nome))]));

    private static async Task<Created<RegistroDeDemonstracaoResponse>> RegistrarAsync(
        RegistroDeDemonstracaoRequest pedido, DemonstracaoHandler handler, HttpContext httpContext, CancellationToken cancellationToken)
    {
        var registro = await handler.RegistrarAsync(pedido.Nome, pedido.Curso, pedido.VersaoDoTermo, cancellationToken);
        return TypedResults.Created(
            (string?)null,
            new RegistroDeDemonstracaoResponse(registro.ChaveDoDispositivo, SessaoHttp.Escrever(httpContext, registro.Sessao)));
    }

    private static async Task<Ok<SessaoResponse>> EntrarAsync(
        EntradaDeDemonstracaoRequest pedido, DemonstracaoHandler handler, HttpContext httpContext, CancellationToken cancellationToken)
    {
        var sessao = await handler.EntrarAsync(pedido.ChaveDoDispositivo, cancellationToken);
        return TypedResults.Ok(SessaoHttp.Escrever(httpContext, sessao));
    }
}

public sealed record DemonstracaoResponse(IReadOnlyList<CursoDeDemonstracao> Cursos);

public sealed record CursoDeDemonstracao(string Sigla, string Nome);

// O nome tem a forma do nome de exibição, conferida no domínio.
public sealed record RegistroDeDemonstracaoRequest(
    [property: Required(AllowEmptyStrings = true), StringLength(240)] string Nome,
    [property: Required, StringLength(16)] string Curso,
    [property: Range(1, int.MaxValue)] int VersaoDoTermo);

public sealed record EntradaDeDemonstracaoRequest([property: Required, StringLength(128)] string ChaveDoDispositivo)
{
    public override string ToString() => "EntradaDeDemonstracaoRequest { }";
}

// A chave do dispositivo vai sempre no corpo, na web também: o app a guarda para voltar,
// e ela só abre a conta de demonstração.
public sealed record RegistroDeDemonstracaoResponse(string ChaveDoDispositivo, SessaoResponse Sessao)
{
    public override string ToString() => "RegistroDeDemonstracaoResponse { }";
}
using System.Security.Cryptography;
using Maxx.Application.Autenticacao;
using Maxx.Application.Autenticacao.Termos;
using Maxx.Application.Fila;
using Maxx.Application.Medalhas;
using Maxx.Domain;
using Maxx.Domain.Academico;
using Maxx.Domain.Identidade;

namespace Maxx.Application.Demonstracao;

// O modo de demonstração da apresentação (produto.md 11). Só existe com a flag ligada; a
// borda nem mapeia as rotas sem ela.
public sealed class DemonstracaoHandler(
    IDemonstracaoRepository demonstracao,
    IUsuarioRepository usuarios,
    SugestaoDeArroba sugestoes,
    SessaoService sessoes,
    TermoDeUsoHandler termos,
    ITokenGenerator tokens,
    IFilaDeTrabalhos fila,
    IUnitOfWork unitOfWork,
    ConfiguracaoDaDemonstracao configuracao,
    TimeProvider relogio)
{
    // Um nome igual de outra pessoa da banca, registrado no mesmo instante, pode pegar o
    // mesmo prefixo: a gravação recusa, e o registro avança para a próxima sugestão livre.
    // Cada recusa de prefixo vem de outro pedido que gravou, então 10 tentativas cobrem até
    // 10 pedidos simultâneos com o mesmo nome.
    private const int _tentativas = 10;

    private const string _alfabetoDoRa = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";

    // Os cursos em que dá para entrar agora: os que têm turma no semestre vigente.
    public Task<IReadOnlyList<Curso>> CursosAsync(CancellationToken cancellationToken) =>
        demonstracao.CursosComTurmaVigenteAsync(Hoje, cancellationToken);

    public async Task<RegistroDeDemonstracao> RegistrarAsync(
        string nome, string siglaDoCurso, int versaoDoTermo, CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(nome);
        ArgumentNullException.ThrowIfNull(siglaDoCurso);

        try
        {
            nome = Usuario.ValidarNomeDeExibicao(nome);
        }
        catch (DomainException excecao)
        {
            throw new RecusaException(TipoDeRecusa.Invalido, CodigosDeRecusa.NomeDeExibicaoInvalido, excecao.Message);
        }

        var termo = await termos.ConferirAceiteAsync(versaoDoTermo, cancellationToken);
        var (curso, turmas) = await demonstracao.TurmasVigentesAsync(siglaDoCurso.Trim(), Hoje, cancellationToken)
            ?? throw new RecusaException(
                TipoDeRecusa.NaoEncontrado, CodigosDeRecusa.CursoDeDemonstracaoIndisponivel, $"Sem turma vigente em {siglaDoCurso}.");

        var recusados = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        for (var tentativa = 1; ; tentativa++)
        {
            var prefixo = await sugestoes.PrimeiroLivreAsync(nome, recusados, cancellationToken);
            var chave = tokens.Generate();
            var cadastro = CadastroElegivel.AlunoDeDemonstracao(GerarRa(), nome, curso);
            var usuario = Usuario.EntrarNaDemonstracao(
                cadastro,
                curso,
                prefixo,
                chave.Hash,
                configuracao.Lote,
                relogio.GetUtcNow());
            usuario.AceitarTermo(termo, relogio.GetUtcNow());

            demonstracao.Adicionar(cadastro);
            foreach (var turma in turmas)
            {
                demonstracao.Adicionar(new Matricula(cadastro, turma));
            }

            usuarios.Adicionar(usuario);

            // Aluno novo muda o divisor da raridade (ADR 0005). Na nova tentativa, o
            // Descartar leva o pedido junto, e ele é feito de novo aqui.
            fila.Enfileirar(new RecalcularRaridade());
            var sessao = sessoes.Abrir(usuario);

            try
            {
                await unitOfWork.SalvarAsync(cancellationToken);
                return new RegistroDeDemonstracao(chave.Valor, sessao);
            }
            catch (ConflitoDeUnicidadeException) when (tentativa == _tentativas)
            {
                throw new RecusaException(
                    TipoDeRecusa.Conflito, CodigosDeRecusa.RegistroSimultaneo, $"Sem arroba livre depois de {_tentativas} tentativas.");
            }
            catch (ConflitoDeUnicidadeException conflito)
            {
                unitOfWork.Descartar();
                if (conflito.Unicidade == Unicidade.Prefixo)
                {
                    recusados.Add(prefixo);
                }

                (curso, turmas) = (await demonstracao.TurmasVigentesAsync(curso.Sigla, Hoje, cancellationToken))!.Value;
            }
        }
    }

    // Voltar pelo mesmo dispositivo abre uma sessão comum, com o refresh rotativo de todo
    // mundo.
    public async Task<Sessao> EntrarAsync(string chaveDoDispositivo, CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(chaveDoDispositivo);

        var usuario = await demonstracao.BuscarPorChaveAsync(tokens.Hash(chaveDoDispositivo.Trim()), cancellationToken)
            ?? throw new RecusaException(
                TipoDeRecusa.NaoAutorizado, CodigosDeRecusa.ChaveDoDispositivoInvalida, "Chave do dispositivo desconhecida.");

        var sessao = sessoes.Abrir(usuario);
        await unitOfWork.SalvarAsync(cancellationToken);
        return sessao;
    }

    private DateOnly Hoje => FusoHorario.DataLocal(relogio.GetUtcNow());

    // Fora do formato numérico dos RAs da faculdade, para nunca colidir com um real.
    private static string GerarRa() => $"DEMO{RandomNumberGenerator.GetString(_alfabetoDoRa, 8)}";
}

// O lote vale para todo aluno de demonstração criado enquanto ele estiver configurado: é a
// chave da purga depois da apresentação.
public sealed record ConfiguracaoDaDemonstracao(string Lote);

// A chave do dispositivo existe só aqui, a caminho do app: o banco guarda o hash.
public sealed record RegistroDeDemonstracao(string ChaveDoDispositivo, Sessao Sessao)
{
    public override string ToString() => "RegistroDeDemonstracao { }";
}

public interface IDemonstracaoRepository
{
    Task<IReadOnlyList<Curso>> CursosComTurmaVigenteAsync(DateOnly hoje, CancellationToken cancellationToken);

    // O curso pela sigla, com as turmas dele no semestre vigente. Nulo se não houver
    // nenhuma.
    Task<(Curso Curso, IReadOnlyList<Turma> Turmas)?> TurmasVigentesAsync(
        string sigla, DateOnly hoje, CancellationToken cancellationToken);

    Task<Usuario?> BuscarPorChaveAsync(string hashDaChave, CancellationToken cancellationToken);

    void Adicionar(CadastroElegivel cadastro);

    void Adicionar(Matricula matricula);
}
using Maxx.Application.Demonstracao;
using Maxx.Domain.Academico;
using Maxx.Domain.Identidade;
using Maxx.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;

namespace Maxx.Infrastructure.Demonstracao;

internal sealed class DemonstracaoRepository(MaxxDbContext db) : IDemonstracaoRepository
{
    public async Task<IReadOnlyList<Curso>> CursosComTurmaVigenteAsync(DateOnly hoje, CancellationToken cancellationToken)
    {
        var vigentes = SemestreVigente.Ids(db, hoje);
        return await db.Set<Curso>()
            .Where(curso => db.Set<Turma>().Any(turma => turma.Materia.CursoId == curso.Id && vigentes.Contains(turma.SemestreLetivoId)))
            .OrderBy(curso => curso.Nome)
            .ToListAsync(cancellationToken);
    }

    public async Task<(Curso Curso, IReadOnlyList<Turma> Turmas)?> TurmasVigentesAsync(
        string sigla, DateOnly hoje, CancellationToken cancellationToken)
    {
        var curso = await db.Set<Curso>().SingleOrDefaultAsync(curso => curso.Sigla == sigla, cancellationToken);
        if (curso is null)
        {
            return null;
        }

        var vigentes = SemestreVigente.Ids(db, hoje);
        var turmas = await db.Set<Turma>()
            .Include(turma => turma.Materia)
            .Where(turma => turma.Materia.CursoId == curso.Id && vigentes.Contains(turma.SemestreLetivoId))
            .ToListAsync(cancellationToken);

        return turmas.Count == 0 ? null : (curso, turmas);
    }

    public Task<Usuario?> BuscarPorChaveAsync(string hashDaChave, CancellationToken cancellationToken) =>
        db.Set<Usuario>().SingleOrDefaultAsync(usuario => usuario.HashDaChaveDoDispositivo == hashDaChave, cancellationToken);

    public void Adicionar(CadastroElegivel cadastro) => db.Add(cadastro);

    public void Adicionar(Matricula matricula) => db.Add(matricula);
}

