namespace Maxx.Domain.Tests.Academico;

public class CadastroElegivelTests
{
    private static readonly Curso _medicina = new("Medicina", "MED", 12);

    [Fact]
    public void Aluno_guarda_ra_curso_e_semestre()
    {
        var aluno = CadastroElegivel.Aluno(" 123456 ", "ana@al.unieduk.com.br", "Ana Souza", _medicina, 12);

        Assert.Equal(Papeis.Aluno, aluno.Papeis);
        Assert.Equal("123456", aluno.Ra);
        Assert.Equal(_medicina.Id, aluno.CursoId);
        Assert.Equal(12, aluno.Semestre);
    }

    [Fact]
    public void Professor_e_coordenacao_de_demonstracao_tem_papel_simples_sem_ra_e_email_reservado()
    {
        var professor = CadastroElegivel.ProfessorDeDemonstracao(" DEMOPROF0001 ", "Rita Lima");
        var coordenacao = CadastroElegivel.CoordenacaoDeDemonstracao("DEMOCOOR0001", "Caio Reis");

        Assert.Equal((Papeis.Professor, "demoprof0001@demonstracao.invalid"), (professor.Papeis, professor.Email));
        Assert.Equal((Papeis.Instituicao, "democoor0001@demonstracao.invalid"), (coordenacao.Papeis, coordenacao.Email));
        Assert.All([professor, coordenacao], cadastro =>
        {
            Assert.True(cadastro.Demonstracao);
            Assert.Null(cadastro.Ra);
            Assert.Null(cadastro.CursoId);
            Assert.Null(cadastro.Semestre);
        });
        Assert.Throws<DomainException>(() => CadastroElegivel.ProfessorDeDemonstracao(" ", "Rita Lima"));
        Assert.Throws<DomainException>(() => CadastroElegivel.CoordenacaoDeDemonstracao("DEMOCOOR0002", " "));
    }

    [Fact]
    public void Professor_de_demonstracao_se_vincula_a_turma()
    {
        var professor = CadastroElegivel.ProfessorDeDemonstracao("DEMOPROF0001", "Rita Lima");
        var coordenacao = CadastroElegivel.CoordenacaoDeDemonstracao("DEMOCOOR0001", "Caio Reis");
        var materia = new Materia("Algoritmos", _medicina, 1);
        var turma = new Turma(materia, new SemestreLetivo(2026, 2, new DateOnly(2026, 8, 1), new DateOnly(2026, 12, 5)));

        Assert.Equal(professor.Id, new VinculoProfessor(professor, turma).ProfessorId);
        Assert.Throws<DomainException>(() => new VinculoProfessor(coordenacao, turma));
    }

    [Theory]
    [InlineData(0)]
    [InlineData(13)]
    public void Semestre_do_aluno_fica_entre_1_e_a_duracao_do_curso(int semestre)
    {
        Assert.Throws<DomainException>(
            () => CadastroElegivel.Aluno("123456", "ana@al.unieduk.com.br", "Ana Souza", _medicina, semestre));
    }

    [Theory]
    [InlineData("")]
    [InlineData("   ")]
    public void Aluno_sem_ra_e_recusado(string ra)
    {
        Assert.Throws<DomainException>(
            () => CadastroElegivel.Aluno(ra, "ana@al.unieduk.com.br", "Ana Souza", _medicina, 1));
    }

    [Theory]
    [InlineData("")]
    [InlineData("ana")]
    [InlineData("@al.unieduk.com.br")]
