57	    public async Task Purga_tira_o_lote_inteiro_numa_transacao_e_manda_as_fotos_para_fora_do_bucket()
58	    {
59	        await using var mundo = await MundoAsync();
60	        var dani = await DemoAsync(mundo, "Dani Demo", "daniDemo", _purgado);
61	        var edu = await DemoAsync(mundo, "Edu Demo", "eduDemo", _vigente);
62	        var fotos = await AtividadeAsync(mundo, dani);
63	        await mundo.EsvaziarFilaAsync();
64	        Assert.All(fotos, chave => Assert.True(mundo.Bucket.ExisteAsync(chave, Ct).Result));
65	        using var coordenacao = await mundo.ComoAsync(Coordenacao);
66	
67	        var resposta = await coordenacao.PostAsJsonAsync(Rota($"/{_purgado}/purga"), new { confirmacao = _purgado }, Ct);
68	
69	        Assert.Equal(HttpStatusCode.OK, resposta.StatusCode);
70	        Assert.Equal(new PurgaResponse(_purgado, 1, fotos.Count), await resposta.Content.ReadFromJsonAsync<PurgaResponse>(Ct));
71	
72	        // Nada do lote fica, e o que é de outra pessoa sobre ele sai junto.
73	        Assert.DoesNotContain(await mundo.LinhasAsync<Usuario>(), usuario => usuario.Id == dani);
74	        Assert.DoesNotContain(await mundo.LinhasAsync<CadastroElegivel>(), linha => linha.NomeCompleto == "Dani Demo");
75	        Assert.DoesNotContain(await mundo.LinhasAsync<Post>(), post => post.AutorId == dani);
76	        Assert.DoesNotContain(await mundo.LinhasAsync<Medalha>(), medalha => medalha.AlunoId == dani);
77	        Assert.DoesNotContain(await mundo.LinhasAsync<Notificacao>(), notificacao => notificacao.UsuarioId == dani);
78	        Assert.DoesNotContain(await mundo.LinhasAsync<UploadPendente>(), upload => upload.UsuarioId == dani);
79	        Assert.DoesNotContain(await mundo.LinhasAsync<Seguimento>(), seguimento => seguimento.SeguidorId == dani || seguimento.SeguidoId == dani);
80	        Assert.DoesNotContain(await mundo.LinhasAsync<Curtida>(), curtida => curtida.UsuarioId == dani);
81	        Assert.Equal(["Bem-vinda!"], (await mundo.LinhasAsync<Comentario>()).Select(comentario => comentario.Texto));
82	
83	        // O resto fica: o outro lote, os alunos de verdade e o post da Ana.
84	        Assert.Contains(await mundo.LinhasAsync<Usuario>(), usuario => usuario.Id == edu);
85	        Assert.Single(await mundo.LinhasAsync<Post>(), post => post.AutorId == mundo.Id(Ana));
86	        var registro = Assert.Single(await mundo.LinhasAsync<PurgaDaDemonstracao>());
87	        Assert.Equal((_purgado, 1, fotos.Count, mundo.Id(Coordenacao)), (registro.Lote, registro.Alunos, registro.Fotos, registro.PurgadoPorId));
88	
89	        var trabalhos = await mundo.LinhasAsync<Trabalho>();
90	        Assert.Single(trabalhos, trabalho => trabalho.Tipo == RemoverFotos.Tipo);
91	        Assert.Single(trabalhos, trabalho => trabalho.Tipo == RecalcularRanking.Tipo);
92	        Assert.Single(trabalhos, trabalho => trabalho.Tipo == RecalcularRaridade.Tipo);
93	
94	        // O worker tira as fotos do bucket.
95	        mundo.Relogio.Avancar(TimeSpan.FromSeconds(11));
96	        await mundo.EsvaziarFilaAsync();
97	        foreach (var chave in fotos)
98	        {
99	            Assert.False(await mundo.Bucket.ExisteAsync(chave, Ct));
100	        }
101	    }
