104	    public async Task Purga_pede_o_lote_digitado_de_novo_vale_para_o_vigente_e_nao_acha_lote_vazio()
105	    {
106	        await using var mundo = await MundoAsync();
107	        await DemoAsync(mundo, "Edu Demo", "eduDemo", _vigente);
108	        using var coordenacao = await mundo.ComoAsync(Coordenacao);
109	        using var renata = await mundo.ComoAsync(Renata);
110	
111	        await AssertRecusaAsync(
112	            await coordenacao.PostAsJsonAsync(Rota($"/{_vigente}/purga"), new { confirmacao = "banca" }, Ct),
113	            HttpStatusCode.BadRequest,
114	            "confirmacao-invalida");
