119	
120	        Assert.Equal(
121	            HttpStatusCode.OK,
122	            (await coordenacao.PostAsJsonAsync(Rota($"/{_vigente}/purga"), new { confirmacao = _vigente }, Ct)).StatusCode);
123	        await AssertRecusaAsync(
124	            await coordenacao.PostAsJsonAsync(Rota($"/{_vigente}/purga"), new { confirmacao = _vigente }, Ct),
125	            HttpStatusCode.NotFound,
126	            "lote-nao-encontrado");
