130	    [Fact]
131	    public async Task Falha_no_meio_da_purga_desfaz_tudo_e_nao_manda_foto_nenhuma_para_fora()
132	    {
133	        await using var mundo = await MundoAsync();
134	        var dani = await DemoAsync(mundo, "Dani Demo", "daniDemo", _purgado);
135	        var fotos = await AtividadeAsync(mundo, dani);
136	        await mundo.EsvaziarFilaAsync();
137	
138	        // Um aviso em nome da Dani, que a purga não apaga (aluno não publica aviso): a chave
139	        // estrangeira recusa apagar a conta dela, depois de o post e a medalha já terem saído.
140	        await using (var scope = mundo.Factory.Services.CreateAsyncScope())
141	        {
142	            await scope.ServiceProvider.GetRequiredService<MaxxDbContext>().Database.ExecuteSqlAsync($"""
143	                INSERT INTO aviso (id, autor_id, escopo, titulo, texto, publicado_em)
144	                VALUES ({Guid.CreateVersion7()}, {dani}, 'faculdade', 'Aviso impossível', 'Só para travar a purga.', now())
145	                """, Ct);
146	        }
147	
148	        using var coordenacao = await mundo.ComoAsync(Coordenacao);
149	        var resposta = await coordenacao.PostAsJsonAsync(Rota($"/{_purgado}/purga"), new { confirmacao = _purgado }, Ct);
150	
151	        Assert.Equal(HttpStatusCode.InternalServerError, resposta.StatusCode);
152	        Assert.Contains(await mundo.LinhasAsync<Usuario>(), usuario => usuario.Id == dani);
153	        Assert.Contains(await mundo.LinhasAsync<Post>(), post => post.AutorId == dani);
154	        Assert.Contains(await mundo.LinhasAsync<Medalha>(), medalha => medalha.AlunoId == dani);
155	        Assert.Empty(await mundo.LinhasAsync<PurgaDaDemonstracao>());
156	        Assert.DoesNotContain(await mundo.LinhasAsync<Trabalho>(), trabalho => trabalho.Tipo == RemoverFotos.Tipo);
157	        foreach (var chave in fotos)
158	        {
159	            Assert.True(await mundo.Bucket.ExisteAsync(chave, Ct));
160	        }
161	    }
