163	    private static Uri Rota(string resto) => new($"/api/v1/instituicao/demonstracao/lotes{resto}", UriKind.Relative);
164	
165	    // A flag da demonstração fica desligada: só o lote vigente é configurado.
166	    private Task<MundoSocial> MundoAsync() =>
167	        CriarAsync(postgres, armazenamento, configuracao: new Dictionary<string, string> { ["Demo:Lote"] = _vigente });
168	
169	    // Um aluno de demonstração do curso, matriculado na turma de Banco de Dados.
170	    private static async Task<Guid> DemoAsync(MundoSocial mundo, string nome, string prefixo, string lote)
171	    {
172	        await using var scope = mundo.Factory.Services.CreateAsyncScope();
173	        var db = scope.ServiceProvider.GetRequiredService<MaxxDbContext>();
174	        var turma = await db.Set<Turma>().Include(turma => turma.Materia).SingleAsync(turma => turma.Id == mundo.Turma, Ct);
175	        var curso = await db.Set<Curso>().SingleAsync(curso => curso.Id == turma.Materia.CursoId, Ct);
176	        var cadastro = CadastroElegivel.AlunoDeDemonstracao($"DEMO{prefixo.ToUpperInvariant()[..4]}{lote[^1]}", nome, curso);
177	        var usuario = Usuario.EntrarNaDemonstracao(cadastro, curso, prefixo, $"hash-{prefixo}", lote, mundo.Relogio.GetUtcNow());
178	        db.AddRange(cadastro, new Matricula(cadastro, turma), usuario);
179	        await db.SaveChangesAsync(Ct);
180	        return usuario.Id;
181	    }
182	
183	    // O que a Dani faz na demonstração: post com foto, foto de perfil, um upload largado,
184	    // medalha, comentário, curtida e seguimento nos dois sentidos com a Ana. O Bruno comenta no
185	    // post da Ana, e esse comentário fica. Devolve as chaves
186	    // das fotos que a purga tem de tirar do bucket.
187	    private static async Task<List<string>> AtividadeAsync(MundoSocial mundo, Guid daniId)
188	    {
189	        await using (var scope = mundo.Factory.Services.CreateAsyncScope())
190	        {
191	            await scope.ServiceProvider.GetRequiredService<ConcederMedalhaHandler>()
192	                .ConcederAsync(mundo.Id(Renata), mundo.Turma, daniId, "M01", Ct);
193	        }
194	
195	        await using var escopo = mundo.Factory.Services.CreateAsyncScope();
196	        var db = escopo.ServiceProvider.GetRequiredService<MaxxDbContext>();
197	        var bucket = escopo.ServiceProvider.GetRequiredService<IArmazenamentoDeFotos>();
198	        var agora = mundo.Relogio.GetUtcNow();
199	        var dani = await db.Set<Usuario>().SingleAsync(usuario => usuario.Id == daniId, Ct);
200	        var ana = await db.Set<Usuario>().SingleAsync(usuario => usuario.Id == mundo.Id(Ana), Ct);
201	        var bruno = await db.Set<Usuario>().SingleAsync(usuario => usuario.Id == mundo.Id(Bruno), Ct);
202	
203	        var doPost = await EnviadoAsync(bucket, dani, FinalidadeDoUpload.Post, agora);
204	        var doPerfil = await EnviadoAsync(bucket, dani, FinalidadeDoUpload.FotoDePerfil, agora);
205	        var largado = await EnviadoAsync(bucket, dani, FinalidadeDoUpload.Post, agora);
206	        var postDaDani = Post.Publicar(dani, "Na palestra de abertura", doPost, null, agora).Post!;
207	        Assert.Null(dani.TrocarFoto(doPerfil, agora).Recusa);
208	        var postDaAna = Post.Publicar(ana, "Primeiro dia!", null, null, agora).Post!;
209	        db.AddRange(doPost, doPerfil, largado, postDaDani, postDaAna);
210	        db.AddRange(
211	            Comentario.Escrever(dani, postDaAna, "Oi, Ana!", agora).Comentario!,
212	            Comentario.Escrever(bruno, postDaAna, "Bem-vinda!", agora).Comentario!,
213	            Comentario.Escrever(ana, postDaDani, "Que legal!", agora).Comentario!,
214	            Curtida.Curtir(dani, postDaAna, agora)!,
215	            Curtida.Curtir(ana, postDaDani, agora)!,
216	            Seguimento.Seguir(ana, dani, professorDoSeguido: false, agora)!,
217	            Seguimento.Seguir(dani, ana, professorDoSeguido: false, agora)!);
218	        await db.SaveChangesAsync(Ct);
219	
220	        return [.. new[] { doPost, doPerfil, largado }.SelectMany(upload => new[] { upload.ChaveDoFeed, upload.ChaveDaGrade })];
221	    }
222	
223	    private static async Task<UploadPendente> EnviadoAsync(
224	        IArmazenamentoDeFotos bucket, Usuario usuario, FinalidadeDoUpload finalidade, DateTimeOffset agora)
225	    {
226	        var upload = UploadPendente.Pedir(usuario, finalidade, "image/jpeg", _feed, _grade, agora).Upload!;
227	        using var http = new HttpClient();
228	        foreach (var (chave, tamanho) in new[] { (upload.ChaveDoFeed, _feed), (upload.ChaveDaGrade, _grade) })
229	        {
230	            var envio = bucket.AssinarEnvio(chave, "image/jpeg", tamanho, DateTimeOffset.UtcNow.AddMinutes(10));
231	            using var corpo = new ByteArrayContent(new byte[tamanho]);
232	            corpo.Headers.ContentType = new MediaTypeHeaderValue("image/jpeg");
233	            Assert.Equal(HttpStatusCode.OK, (await http.PutAsync(envio.Url, corpo, Ct)).StatusCode);
234	        }
235	
236	        return upload;
237	    }
238	}
