    await ateOTermo(" Rita Lima ");
    await apertar("Aceitar e entrar");

    expect(await professores.mock.calls[0]![0].json()).toEqual({
      nome: "Rita Lima",
      curso: "CC",
      versaoDoTermo: 1,
