1	// Os três papéis da demonstração (passo 14). Coordenação é o rótulo da conta com o papel de
2	// instituição.
3	export type PapelDeDemonstracao = "aluno" | "professor" | "coordenacao";
4	
5	const PAPEIS: readonly string[] = ["aluno", "professor", "coordenacao"];
6	
7	// Uma conta de demonstração lembrada neste aparelho: a chave que abre a conta sem senha,
8	// e o que mostrar na lista para a pessoa reconhecer a sua. Curso vazio na coordenação.
9	export interface ContaDeDemonstracao {
10	  chave: string;
11	  nome: string;
12	  curso: string;
13	  papel: PapelDeDemonstracao;
14	}
15	
16	// O que estiver guardado e não tiver a forma esperada é descartado: lista vazia, nunca
17	// uma tela quebrada. A conta guardada antes do passo 14 não tem papel, e é de aluno.
18	export function analisarContas(guardado: string | null): ContaDeDemonstracao[] {
19	  if (!guardado) {
20	    return [];
21	  }
22	
23	  try {
24	    const valor: unknown = JSON.parse(guardado);
25	    return Array.isArray(valor)
26	      ? valor
27	          .filter(
28	            (
29	              conta,
30	            ): conta is Omit<ContaDeDemonstracao, "papel"> & {
31	              papel?: string;
32	            } =>
33	              typeof conta === "object" &&
34	              conta !== null &&
35	              typeof conta.chave === "string" &&
36	              typeof conta.nome === "string" &&
37	              typeof conta.curso === "string" &&
38	              (conta.papel === undefined || PAPEIS.includes(conta.papel)),
39	          )
40	          .map((conta) => ({
41	            chave: conta.chave,
42	            nome: conta.nome,
43	            curso: conta.curso,
44	            papel: (conta.papel ?? "aluno") as PapelDeDemonstracao,
45	          }))
46	      : [];
47	  } catch {
48	    return [];
49	  }
50	}
51	
52	// O botão da lista "Neste aparelho".
53	export function rotuloDaConta(conta: ContaDeDemonstracao): string {
