// Capturas da etapa 6 (passo 14): a tela da purga, só no compose local (lote captura-local).
// Cria pela demonstração um aluno, um professor e uma coordenação de teste, entra como a
// coordenação, e captura a lista, o modal e o resultado da purga do próprio lote, no claro
// e no escuro. Cada tema purga o lote que criou; nada sai desta máquina.
// Uso: node capturar-purga.cjs <raiz do repositório> <pasta de saída>
const path = require("node:path");
const [raiz, saida] = process.argv.slice(2);
const { chromium, request } = require(path.join(raiz, "node_modules", "@playwright", "test"));

const base = process.env.MAXX_BASE_URL ?? "http://localhost";
const LOTE = "captura-local";

(async () => {
  const api = await request.newContext({ baseURL: base });
  const termo = (await (await api.get("/api/v1/termo-de-uso")).json()).versao;
  const navegador = await chromium.launch();

  for (const tema of ["light", "dark"]) {
    const nomeDoTema = tema === "light" ? "claro" : "escuro";
    // A equipe e um aluno do lote, pela API, como a tela de demonstração faria.
    await api.post("/api/v1/demo/alunos", { data: { nome: "Aluno Captura", curso: "CC", versaoDoTermo: termo } });
    await api.post("/api/v1/demo/professores", { data: { nome: "Professor Captura", curso: "CC", versaoDoTermo: termo } });

    const contexto = await navegador.newContext({ viewport: { width: 1280, height: 900 }, colorScheme: tema });
    const pagina = await contexto.newPage();
    const tirar = async (nome) => {
      await pagina.waitForTimeout(500);
      await pagina.screenshot({ path: path.join(saida, `purga-${nome}-${nomeDoTema}.png`) });
    };

    // A coordenação entra pela tela, como a banca.
    await pagina.goto(`${base}/demonstracao`);
    await pagina.getByRole("button", { name: "Entrar como coordenação" }).click();
    await pagina.getByLabel("Nome").fill("Conferência Maxx");
    await pagina.getByRole("button", { name: "Continuar" }).click();
    await pagina.getByRole("button", { name: "Aceitar e entrar" }).click();
    await pagina.waitForURL((url) => !url.pathname.startsWith("/demonstracao"));

    await pagina.goto(`${base}/instituicao/purga`);
    await pagina.getByTestId(`lote-${LOTE}`).waitFor();
    await tirar("1-lista");

    await pagina.getByRole("button", { name: `Purgar o lote ${LOTE}` }).click();
    await pagina.getByLabel("Nome do lote").fill(LOTE);
    await tirar("2-modal");

    await pagina.getByTestId("folha-de-ato").getByRole("button", { name: "Purgar lote" }).click();
    await pagina.getByTestId("purga-concluida").waitFor();
    await tirar("3-resultado");

    await pagina.getByRole("button", { name: "Voltar ao login" }).click();
    await pagina.waitForURL(/\/login$/);
    await tirar("4-login");

    await contexto.close();
  }

  await navegador.close();
  await api.dispose();
})().catch((erro) => {
  console.error(erro);
  process.exit(1);
});

